# Real-data diagnostic of advanced Heatmap violin values and CSV. Runs the
# actual production reactive and download content with Shiny inputs isolated.
# PRIVATE_HUB_RDS is generated by test_real_project_hub_parity.R; no values or
# sample identifiers are printed. A nonzero exit signals a scale mismatch.
source('R/global.R')
p <- Sys.getenv('PRIVATE_HUB_RDS'); if(!nzchar(p)) stop('Set PRIVATE_HUB_RDS')
res <- readRDS(p)
find_ast <- function(node, pred) {
  if(pred(node)) return(node)
  if(is.recursive(node)) for(i in seq_along(node)) {
    v <- tryCatch(find_ast(node[[i]],pred),error=function(e)NULL)
    if(!is.null(v)) return(v)
  }
  NULL
}
ast <- parse('R/modules/4_heatmap_module.R')
violin_expr <- find_ast(ast,function(x) is.call(x)&&identical(x[[1]],as.name('<-'))&&identical(x[[2]],as.name('build_heatmap_violin_ggplot')))
csv_expr <- find_ast(ast,function(x) is.call(x)&&identical(x[[1]],as.name('<-'))&&is.call(x[[2]])&&identical(x[[2]][[1]],as.name('$'))&&identical(x[[2]][[2]],as.name('output'))&&identical(x[[2]][[3]],as.name('download_violin_csv')))
stopifnot(!is.null(violin_expr),!is.null(csv_expr))
for(policy in c('classic','team')) {
 d<-res[[policy]]; value<-function(x){force(x);function(...)x}; m<-d$matrix; targets<-m$Lipid_Name[1:3]
 e<-new.env(parent=globalenv()); e$shared_data<-list(data_processed=value(m),all_metadata=value(d$metadata),class_color_map=value(d$class_colors))
 e$get_active_violin_lipids<-value(targets);e$input<-shiny::reactiveValues(violin_scale_mode='log2',violin_sample_mode='group_distribution',show_violin_sig=FALSE)
 e$plot_logratio_violin<-function(df,...) df
 eval(violin_expr,e)
 logged<-shiny::isolate(e$build_heatmap_violin_ggplot())
 e$input$violin_scale_mode<-'linear'; linear<-shiny::isolate(e$build_heatmap_violin_ggplot())
 handler<-eval(csv_expr[[3]][['content']],e);out<-tempfile(fileext='.csv');shiny::isolate(handler(out));csv<-read.csv(out,check.names=FALSE);unlink(out)
 idx<-cbind(match(logged$Feature,m$Lipid_Name),match(logged$Sample_ID,names(m)))
 idx[,2]<-idx[,2]-1L; orig<-as.matrix(m[-1])[idx]
 stopifnot(length(orig)==201L,nrow(csv)==201L)
 csv_idx<-cbind(match(csv$Lipid_Name,m$Lipid_Name),match(csv$Sample_ID,names(m)))
 csv_idx[,2]<-csv_idx[,2]-1L; rawcsv<-as.matrix(m[-1])[csv_idx]
 logged_ok<-all(is.finite(logged$Plot_Value)) && max(abs(logged$Plot_Value-log2(orig)))<1e-10
 linear_ok<-all(is.finite(linear$Plot_Value)) && max(abs(linear$Plot_Value-orig))<1e-7
 csv_ok<-max(abs(csv$Log2_Abundance-log2(rawcsv)))<1e-10
 cat(sprintf('%s: 3 lipids x 67 samples: log2_plot_correct=%s linear_plot_correct=%s csv_log2_correct=%s; linear_nonfinite=%d; CSV_matches_untransformed=%s\n',policy,logged_ok,linear_ok,csv_ok,sum(!is.finite(linear$Plot_Value)),isTRUE(all.equal(csv$Log2_Abundance,rawcsv,tolerance=1e-12))))
 # Edge cases only probe transformation mechanics; no biological values are fabricated.
 edge <- data.frame(Lipid_Name=targets[1],S1=0,S2=-1,S3=NA_real_,S4=8,check.names=FALSE)
 edge_meta <- data.frame(FullName=c('S1','S2','S3','S4'),Group1=c('A','A','B','B'))
 e$shared_data$data_processed<-value(edge);e$shared_data$all_metadata<-value(edge_meta)
 e$get_active_violin_lipids<-value(targets[1]);e$input$violin_scale_mode<-'log2'
 edge_plot<-shiny::isolate(e$build_heatmap_violin_ggplot())
 edge_file<-tempfile(fileext='.csv');shiny::isolate(handler(edge_file));edge_csv<-read.csv(edge_file);unlink(edge_file)
 edge_ok<-nrow(edge_plot)==1L && edge_plot$Plot_Value[1]==3 &&
   all(is.na(edge_csv$Log2_Abundance[1:3])) && edge_csv$Log2_Abundance[4]==3
 cat(sprintf('%s: zero/negative/missing log2 handling correct=%s\n',policy,edge_ok))
 if(!logged_ok||!linear_ok||!csv_ok||!edge_ok) failure<-TRUE
}
if(exists('failure')) stop('Advanced violin scale mismatch: see aggregate diagnostics above')
